function riskFlags(best, platform, region, edition, prefs) {
  const flags = [];
  if (!best.channel.physical && prefs.wantsCancel) {
    flags.push({
      title: "Sua janela de reembolso fecha no preload, não no lançamento",
      body: `Em ${platform.label}, uma pré-venda digital deixa de ser reembolsável no momento em que o download começa, cerca de ${platform.preloadLeadDays} dia${platform.preloadLeadDays === 1 ? "" : "s"} antes do lançamento. Se manter a opção de desistir importa mais que jogar no desbloqueio, não comece o preload.`,
      severity: "high"
    });
  }
  if (best.channel.id === "retailer-code" && prefs.wantsPreload) {
    flags.push({
      title: "Um código tardio pode custar seu preload",
      body: "Códigos digitais de varejista costumam ser entregues 24 a 72 horas antes do lançamento. Isso cai dentro da janela de preload no Xbox e pode ficar apertado no PlayStation, então você pode estar baixando no dia do lançamento.",
      severity: "medium"
    });
  }
  if (best.channel.physical) {
    flags.push({
      title: "Discos ainda baixam um patch do primeiro dia",
      body: "Um disco remove o download base, mas não o patch de lançamento. Reserve largura de banda de qualquer forma e espere instalar por um tempo antes de jogar.",
      severity: "medium"
    });
  }
  if (best.channel.id === "marketplace-key") {
    flags.push({
      title: "Chaves do mercado cinza trazem risco de revogação",
      body: "Uma chave revogada normalmente significa sem jogo e sem reembolso, e o suporte da editora não vai intervir em um direito que ela não vendeu. A economia raramente vale a exposição em um título de lançamento.",
      severity: "high"
    });
  }
  if (edition.id !== "standard") {
    flags.push({
      title: `Os bônus de ${edition.label} ficam presos à conta compradora`,
      body: `${edition.note} Trocar de canal ou plataforma depois de pedir significa comprar o pacote de bônus de novo, então decida a plataforma antes da edição.`,
      severity: "low"
    });
  }
  if (region.consumerLaw >= 8 && !best.channel.physical) {
    flags.push({
      title: "Você tem um direito legal de cancelamento, use-o antes de baixar",
      body: `${region.note} Esse direito normalmente sobrevive só enquanto o conteúdo digital não foi baixado, que é o mesmo limite que a loja aplica.`,
      severity: "low"
    });
  }
  return flags;
}
export function rankChannels(input) {
  const platform = platformById(input.platform) ?? PLATFORMS[0];
  const region = regionById(input.region) ?? REGIONS[0];
  const edition = editionById(input.edition) ?? EDITIONS[0];
  const prefs = input.prefs;
  const weights = weightsFor(prefs);
  const ranked = CHANNELS.filter((c) => c.platforms.includes(platform.id)).map((channel) => {
    const adj = adjustedAxes(channel, platform, region, edition);
    const axes = Object.keys(AXIS_LABELS).map((id) => ({
      id,
      label: AXIS_LABELS[id],
      raw: adj[id],
      weight: weights[id],
      detail: AXIS_DETAIL[id]
    }));
    const score = Math.round(axes.reduce((sum, a) => sum + a.raw / 10 * a.weight, 0) * 10) / 10;
    const sorted = [...axes].sort((a, b) => b.raw - a.raw);
    return {
      channel,
      score,
      axes,
      strengths: sorted.slice(0, 2).filter((a) => a.raw >= 6).map((a) => a.label),
      risks: sorted.slice(-2).filter((a) => a.raw <= 4).map((a) => a.label),
      confidence: channel.confidence
    };
  }).sort((a, b) => b.score - a.score || a.channel.label.localeCompare(b.channel.label));
  const best = ranked[0];
  const runnerUp = ranked[1];
  const wanted = [
    prefs.wantsPreload ? "jogar no momento do desbloqueio" : null,
    prefs.wantsCancel ? "manter a opção de cancelar" : null,
    prefs.wantsResale ? "valor de revenda ou empréstimo" : null
  ].filter(Boolean);
  const priorities = wanted.length === 0 ? "sem uma preferência forte além do valor" : wanted.length === 1 ? wanted[0] : `${wanted.slice(0, -1).join(", ")} e ${wanted.at(-1)}`;
  const headline = `${best.channel.short} em ${platform.label}`;
  const reason = `Porque você nos disse que ${priorities} importa, ${best.channel.label.toLowerCase()} marca ${best.score} de 100 para um pedido de ${edition.label} em ${region.label}, liderando em ${best.strengths.join(" e ").toLowerCase() || "equilíbrio geral"}${runnerUp ? `, à frente de ${runnerUp.channel.short.toLowerCase()} com ${runnerUp.score}` : ""}.`;
  return {
    platform,
    region,
    edition,
    prefs,
    weights,
    ranked,
    best,
    runnerUp,
    headline,
    reason,
    riskFlags: riskFlags(best, platform, region, edition, prefs),
    timeline: timeline(platform, region)
  };
}
